import pypdf
print("pypdf version:", pypdf.__version__)

import os

# Look for TrueType fonts in common locations
font_paths = []
for root in ["/usr/share/fonts", "/usr/local/share/fonts", "/System/Library/Fonts"]:
    if os.path.isdir(root):
        for dirpath, dirnames, filenames in os.walk(root):
            for fn in filenames:
                if fn.lower().endswith(".ttf") or fn.lower().endswith(".ttc"):
                    font_paths.append(os.path.join(dirpath, fn))
for p in font_paths[:30]:
    print("FONT:", p)
print("Total fonts found:", len(font_paths))
